"""Build the Spanish OAF self-study programme. Source: normas_oaf_2022.pdf, pp. 8,14–17."""
import sys
sys.dont_write_bytecode=True
import html,json
from pathlib import Path
from oaf_content import AREAS,UNITS
ROOT=Path(__file__).resolve().parent.parent
E=lambda v:html.escape(str(v),quote=True)
def dump(v):return json.dumps(v,ensure_ascii=False,indent=2)
def write(path,text):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def shell(title,prefix,body,script=''):
 return f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173d57"><title>{E(title)} | OAF · Learning Lab</title><meta name="description" content="Preparación autónoma de física en español: {E(title)}. Lecciones, ejemplos, pistas, repaso e investigaciones guiadas."><link rel="icon" type="image/png" href="{prefix}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{prefix}assets/oaf/oaf.css?v=1"><link rel="stylesheet" href="{prefix}assets/desktop-layout.css?v=desktop-1">{script}</head><body><a class="skip" href="#main">Saltar al contenido</a><header class="topbar"><a class="brand" href="{prefix}index.html"><img src="{prefix}assets/brand/learning-lab-logo.png" width="44" height="44" alt="">learning<span>lab</span></a><nav aria-label="Navegación principal"><a href="{prefix}index.html#/years">Años y programas</a><a href="{prefix}activities/oaf/">OAF</a><a href="{prefix}activities/oaf/programa.html">Programa y normas</a></nav></header>{body}<footer class="footer"><span>Learning Lab · Física para observar, medir y explicar</span><a href="{prefix}activities/oaf/programa.html#estudiar">Cómo estudiar por tu cuenta</a></footer><noscript><p class="notice">Las lecciones y ejemplos pueden leerse sin JavaScript. Activá JavaScript para usar los instrumentos, corregir preguntas y guardar avances.</p></noscript></body></html>'''
def section(number,kicker,title):return f'<div class="section-title"><span>{number:02}</span><div><p class="eyebrow">{kicker}</p><h2>{title}</h2></div></div>'
def card(u,base=''):
 return f'<a class="unit-tile" href="{base}{u["path"]}"><span class="tag">UNIDAD {u["order"]:02} · 4 LECCIONES</span><h2>{E(u["title"])}</h2><p>{E(" · ".join(l["title"] for l in u["lessons"]))}</p><span class="tile-end">Estudiar · investigar · repasar <b>→</b></span><small data-progress="{u["id"]}">0 de 4 lecciones comprobadas</small></a>'
write(Path('assets/oaf/course.json'),dump(dict(areas=AREAS,units=UNITS))+'\n')
area_by_id={a['id']:a for a in AREAS}
cover='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 330"><rect width="600" height="330" rx="24" fill="#173d57"/><circle cx="430" cy="143" r="96" fill="none" stroke="#759dbd" stroke-width="2" stroke-dasharray="5 7"/><circle cx="430" cy="143" r="46" fill="#72b5be"/><circle cx="514" cy="98" r="12" fill="#edbd73"/><path d="M50 234Q76 114 102 234T154 234T206 234T258 234" fill="none" stroke="#80cccd" stroke-width="5"/><path d="M58 266H290" stroke="#8ea9be" stroke-width="2"/><rect x="88" y="90" width="145" height="52" rx="10" fill="#b7d3e7"/><circle cx="118" cy="151" r="13" fill="#edbd73"/><circle cx="205" cy="151" r="13" fill="#edbd73"/><path d="M242 114H310m-15-11 16 11-16 11" fill="none" stroke="#edbd73" stroke-width="5"/><text x="36" y="42" fill="#b9dbe3" font-family="sans-serif" font-size="14" letter-spacing="3">LEARNING LAB / OAF</text><text x="300" y="289" text-anchor="middle" fill="#edbd73" font-family="sans-serif" font-size="18">MEDIR · MODELAR · EXPLICAR</text></svg>'''
write(Path('activities/oaf/cover.svg'),cover)
search='''<div class="topic-search" id="topic-search"><label for="topic-query">Buscá por tema</label><p id="topic-search-help">Probá: encuentros, Arquímedes, energía, circuitos, lentes o fotones.</p><div class="topic-search-field"><input id="topic-query" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="topic-matches" aria-describedby="topic-search-help" autocomplete="off" placeholder="Escribí un tema…" disabled><div class="topic-popup" id="topic-popup" hidden><ul id="topic-matches" role="listbox" aria-label="Coincidencias"></ul></div></div><p id="topic-search-status" class="search-status" role="status">Cargando temas…</p></div>'''
areas=''.join(f'<a class="area-card" href="{a["id"]}/"><span class="tag">{sum(u["area"]==a["id"] for u in UNITS)} UNIDADES</span><h3>{E(a["name"])}</h3><p>{E(a["intro"])}</p><b>Explorar el área →</b></a>' for a in AREAS)
body=f'''<main id="main" tabindex="-1"><section class="oaq-hero"><div><p class="eyebrow">OLIMPÍADA ARGENTINA DE FÍSICA · PREPARACIÓN EN ESPAÑOL</p><h1>Hacé preguntas.<br><em>Poné la física a prueba.</em></h1><p>Aprendé por tu cuenta con explicaciones, ejemplos resueltos, reglas para recordar e instrumentos que vos hacés funcionar.</p>{search}<a class="button" href="#areas">Elegí un área ↓</a></div><div class="hero-art"><img src="cover.svg" alt="Carro, onda y órbita: modelos físicos para investigar"><span>PREDECIR → INVESTIGAR → COMPARAR → EXPLICAR</span></div></section>{section(1,'DOS RUTAS PARA UN PROGRAMA COMÚN','Elegí cómo querés trabajar.')}<div class="route-grid"><a class="unit-tile" href="nivel-1/"><span class="tag">RUTA DE ESTUDIO · BASE</span><h2>Preparación Nivel 1</h2><p>Construí fundamentos con las lecciones, ejemplos y primeros ensayos de todas las áreas.</p><span class="tile-end">Empezar por la base →</span></a><a class="unit-tile" href="nivel-2/"><span class="tag">RUTA DE ESTUDIO · PROFUNDIZACIÓN</span><h2>Desafíos para Nivel 2</h2><p>Combiná ideas, analizá límites de los modelos y compará investigaciones después de completar la base.</p><span class="tile-end">Profundizar y justificar →</span></a></div><p class="route-note">Según las normas 2022, Nivel 2 agrega una extensión de mayor complejidad a la prueba básica. El PDF no divide un temario por nivel; estas rutas son una organización didáctica de Learning Lab.</p><section id="areas">{section(2,'PROGRAMA ESQUEMÁTICO Y HABILIDADES EXPERIMENTALES','Seis puertas para explorar física.')}<div class="area-grid">{areas}</div></section><section>{section(3,'UNA RUTINA SIN DEPENDER DE UN PROFESOR','Estudiá una idea y contrastala.')}<div class="three-grid"><article><h3>Comprendé y resolvé</h3><p>Revisá los requisitos, leé una explicación y resolvé el desafío antes de abrir el ejemplo. Usá la pista y el control para detectar dudas.</p></article><article><h3>Investigá con instrumentos</h3><p>Guardá una predicción. Mové el material al destino y operá el montaje sobre la mesa. Si te trabás, la ayuda completa solo ese paso.</p></article><article><h3>Compará y retomá</h3><p>Registrá dos condiciones, explicá lo que cambia y terminá con repaso. Los enlaces y reintentos te llevan a la lección que necesitás revisar.</p></article></div></section><aside class="notice">Material original de preparación, independiente de la organización oficial OAF. Basado en <cite>Normas Generales de OAF 2022</cite>, especialmente pp. 8 y 14–17. <a href="programa.html">Consultá fuente, normas y correspondencia</a>. El avance y los resultados permanecen en este navegador.</aside></main>'''
write(Path('activities/oaf/index.html'),shell('OAF · Estudio e investigaciones','../../',body,'<script type="module" src="../../assets/oaf/progress.js?v=1"></script><script type="module" src="../../assets/oaf/search.js?v=1"></script>'))
for a in AREAS:
 units=[u for u in UNITS if u['area']==a['id']]
 b=f'''<main id="main" tabindex="-1"><nav class="crumbs"><a href="../">OAF</a><span>›</span><span>{E(a['name'])}</span></nav><section class="unit-heading"><p class="eyebrow">PROGRAMA COMÚN · OAF</p><h1>{E(a['name'])}</h1><p>{E(a['intro'])}</p><p class="unit-prerequisites">Recorré cada unidad en orden: explicación → ejemplo → control → laboratorio → repaso. Si necesitás reforzar unidades y gráficos, empezá por <a href="../herramientas/medicion/">Herramientas experimentales</a>.</p></section><div class="unit-grid">{''.join(card(u,'../') for u in units)}</div><aside class="notice">Correspondencia con el programa: páginas {a['source']} de las normas 2022. Las áreas no son niveles oficiales separados. <a href="../programa.html">Ver el mapa de contenidos</a>.</aside></main>'''
 write(Path(f'activities/oaf/{a["id"]}/index.html'),shell(a['name'],'../../../',b,'<script type="module" src="../../../assets/oaf/progress.js?v=1"></script>'))
for number in [1,2]:
 title='Preparación Nivel 1' if number==1 else 'Desafíos para Nivel 2'
 intro='Trabajá los fundamentos de cada unidad, comprobá las ideas y hacé el primer ensayo.' if number==1 else 'Completá primero la base. Retomá las ampliaciones, contrastá dos condiciones y justificá resultados usando más de una idea.'
 links=''.join(f'<a class="unit-tile" href="../{u["path"]}#leccion-{1 if number==1 else 4}"><span class="tag">{E(area_by_id[u["area"]]["name"])}</span><h2>{E(u["title"])}</h2><p>{E(u["lessons"][0 if number==1 else 3]["title"])}</p><span class="tile-end">Abrir ruta de estudio →</span><small data-progress="{u["id"]}">0 de 4 lecciones comprobadas</small></a>' for u in UNITS)
 b=f'<main id="main" tabindex="-1"><nav class="crumbs"><a href="../">OAF</a><span>›</span><span>{title}</span></nav><section class="unit-heading"><p class="eyebrow">RUTA DIDÁCTICA DE LEARNING LAB</p><h1>{title}</h1><p>{intro}</p></section><aside class="notice">El apartado 5.2.2 (p. 8) define Nivel 1 como prueba básica y Nivel 2 como básica más extensión. No asigna temas exclusivos a cada nivel. Los accesos siguientes orientan el estudio del programa común y no sustituyen la asignación oficial ni clasifican automáticamente al estudiante.</aside><div class="unit-grid">{links}</div></main>'
 write(Path(f'activities/oaf/nivel-{number}/index.html'),shell(title,'../../../',b,'<script type="module" src="../../../assets/oaf/progress.js?v=1"></script>'))
for u in UNITS:
 a=area_by_id[u['area']];nav='';articles=''
 for i,l in enumerate(u['lessons']):
  nav+=f'<a href="#leccion-{i+1}" data-lesson-link="{i}"><span>{i+1:02}</span>{E(l["title"])}<small data-complete="{i}" aria-label="Pendiente">○</small></a>'
  articles+=f'''<article class="lesson-card" id="leccion-{i+1}" data-lesson="{i}"><p class="eyebrow">LECCIÓN {i+1} / 4 · LEÉ, APLICÁ Y COMPROBÁ</p><h3>{E(l['title'])}</h3>{''.join('<p>'+E(p)+'</p>' for p in l['text'])}<div class="formula">{E(l['formula'])}</div><div class="worked-problem"><span class="tag">INTENTÁ RESOLVER ANTES DE MIRAR</span><p>{E(l['example'][0])}</p><p><strong>Tu desafío:</strong> {E(l['task'])}</p></div><details class="worked"><summary>Ver el ejemplo resuelto paso a paso</summary><ol>{''.join('<li>'+E(p)+'</li>' for p in l['example'][1:])}</ol></details><aside class="memory"><span class="tag">PARA RECORDAR Y ENTENDER</span><h4>{E(l['memory']['cue'])}</h4><p>{E(l['memory']['reason'])}</p></aside><aside class="trap"><strong>Prestá atención.</strong> {E(l['trap'])}</aside><fieldset class="lesson-check" data-check="{i}"><legend>{E(l['check']['prompt'])}</legend><button type="button" class="button secondary" data-hint="{i}" aria-expanded="false">Necesito una pista</button><p class="hint-feedback" data-hint-text="{i}" hidden>Relacioná: {E(l['memory']['cue'])} Revisá {E(l['formula'])}.</p><div class="answers">{''.join(f'<button type="button" data-answer="{j}">{E(o)}</button>' for j,o in enumerate(l['check']['options']))}</div><p class="feedback" role="status"></p></fieldset><button class="button secondary" data-next="{i+1}">{'Siguiente lección →' if i<3 else 'Ir al laboratorio ↓'}</button></article>'''
 b=f'''<main id="main" tabindex="-1" data-unit="{u['id']}"><nav class="crumbs"><a href="../../">OAF</a><span>›</span><a href="../">{E(a['name'])}</a><span>›</span><span>Unidad {u['order']:02}</span></nav><section class="unit-heading"><p class="eyebrow">OAF · UNIDAD {u['order']:02} · {E(a['name'].upper())}</p><h1>{E(u['title'])}</h1><p>Una idea, un modelo y una experiencia para contrastarlo. Comprobá cada explicación y volvé a intentarlo cuando lo necesites.</p><div class="progress-strip"><progress id="unit-progress" max="4" value="0" aria-label="Lecciones comprobadas"></progress><span id="progress-label">0 de 4 lecciones comprobadas</span><span id="storage-note">Avance guardado en este navegador</span></div></section><aside class="unit-prerequisites"><strong>Antes de empezar.</strong> {E(u['before'])} <a href="../../herramientas/medicion/">Repasar herramientas de medición y gráficos →</a><br><strong>Meta:</strong> comprender las cuatro ideas, completar un montaje, comparar dos condiciones y justificar una conclusión. No necesitás una cuenta ni un profesor para corregir estas actividades.</aside><details class="syllabus"><summary>Contenidos y correspondencia con el programa</summary><ul>{''.join('<li>'+E(t)+'</li>' for t in u['topics'])}</ul><p>Normas OAF 2022, programa esquemático y contenidos conceptuales/procedimentales, pp. {a['source']}. <a href="../../programa.html">Ver fuente y alcance</a>.</p></details><section id="estudiar">{section(1,'COMPRENDÉ Y COMPROBÁ','Tu ruta de estudio.')}<div class="study-layout"><nav class="lesson-nav" aria-label="Lecciones de esta unidad">{nav}<a href="#laboratorio"><span>LAB</span>Investigación guiada</a><a href="#repaso"><span>✓</span>Repaso</a><a href="../">← Todas las unidades del área</a></nav><div id="lesson-content">{articles}</div></div></section><section id="laboratorio">{section(2,'PREDECÍ · ARMÁ · MEDÍ · EXPLICÁ','La física en tus manos.')}<div id="oaf-lab"><p role="status">Preparando el laboratorio virtual…</p></div></section><section id="repaso" class="review-section">{section(3,'LISTO PARA PONER A PRUEBA TU COMPRENSIÓN','Practicá, revisá y volvé a la idea.')}<p>Ocho preguntas por unidad, con áreas y niveles seleccionables. La autoevaluación avanza al guardar; al final podés revisar explicaciones y reintentar errores. Es práctica local, no un examen oficial ni un envío al panel docente.</p><div id="review-app"></div></section><nav class="unit-bottom"><a class="button secondary" href="../">← Volver al área</a><a class="button" href="../../">Elegir otro tema →</a></nav></main><script type="application/json" id="unit-data">{dump(u).replace('<',chr(92)+'u003c')}</script>'''
 write(Path('activities/oaf/'+u['path']+'index.html'),shell(u['title'],'../../../../',b,'<script type="module" src="../../../../assets/oaf/lesson.js?v=1"></script>'))
rows=''.join(f'<tr><th>{E(area_by_id[u["area"]]["name"])}</th><td><a href="{u["path"]}">{E(u["title"])}</a><ul>'+''.join('<li>'+E(t)+'</li>' for t in u['topics'])+f'</ul></td><td>{area_by_id[u["area"]]["source"]}</td></tr>' for u in UNITS)
b=f'''<main id="main" tabindex="-1"><nav class="crumbs"><a href="./">OAF</a><span>›</span><span>Programa y normas</span></nav><section class="unit-heading"><p class="eyebrow">FUENTE Y ALCANCE</p><h1>Un programa común, dos niveles de prueba.</h1><p>Sección basada en el archivo <cite>normas_oaf_2022.pdf</cite> aportado por el docente, titulado <cite>Normas Generales de OAF 2022</cite>. Las páginas son las impresas del documento. Las explicaciones, problemas y modelos son originales de Learning Lab, independiente de la organización oficial.</p></section><aside class="notice"><strong>Edición 2022.</strong> Esta ruta sigue el documento compartido. El propio reglamento indica que las normas se editan anualmente (p. 17); para inscripciones, equipamiento permitido y competencias consultá las normas vigentes. Las condiciones de la prueba oficial no son restricciones de uso de esta web de estudio.</aside>{section(1,'QUÉ DICE EL DOCUMENTO','Niveles y evaluación.')}<div class="three-grid"><article><h3>Nivel 1</h3><p>La instancia nacional contempla una prueba básica para todos los participantes (apartado 5.2.2, p. 8).</p></article><article><h3>Nivel 2</h3><p>Incluye la prueba básica más una extensión de mayor complejidad. El PDF no distribuye un temario distinto por nivel; las rutas de esta plataforma son una orientación didáctica (p. 8).</p></article><article><h3>Teoría y experimento</h3><p>El documento describe tres problemas teóricos de áreas diferentes y un problema experimental, en dos días, con un máximo de cuatro horas para cada parte (apartados 5.2.3 y 5.2.3.1, p. 8). Nuestro repaso breve no reproduce esa evaluación.</p></article></div>{section(2,'CORRESPONDENCIA CON EL PROGRAMA','Mapa de contenidos.')}<p>Las cinco áreas temáticas del programa esquemático (pp. 14–15) se complementan con los contenidos conceptuales y procedimentales (pp. 15–17). La unidad de herramientas es transversal y la agrupación de radiación y materia es editorial: no se presenta como un nivel oficial separado.</p><div class="table-wrap"><table><thead><tr><th>Área</th><th>Unidad y contenidos abordados</th><th>Páginas</th></tr></thead><tbody>{rows}</tbody></table></div><section id="estudiar">{section(3,'CÓMO ESTUDIAR SIN DEPENDER DE OTRA PERSONA','Usá la devolución para decidir tu próximo paso.')}<ol class="study-instructions"><li>Revisá los requisitos. Si una ecuación no se entiende, volvé a unidades, gráficos o el tema previo.</li><li>Leé una lección y su asociación para recordar; la explicación indica por qué funciona y cuándo no conviene generalizarla.</li><li>Resolvé el desafío en papel antes de abrir los pasos. Después comprobá una idea y pedí pista si te equivocás.</li><li>Guardá una predicción, arrastrá o seleccioná el instrumento y colocalo en el destino. Operá interruptores, cursores y elementos naranjas sobre la mesa. La ayuda completa solo el paso actual.</li><li>Registrá dos ensayos variando una causa. Compará unidades, relaciones y condiciones del modelo; respondé la pregunta de explicación.</li><li>Terminá con práctica o autoevaluación, revisá errores y seguí el enlace a la lección correspondiente.</li></ol><h2>Modelos y límites</h2><p>Los laboratorios muestran hipótesis, constantes, escalas y unidades. Algunas escenas aceleran el tiempo; en órbitas el ángulo visual es ilustrativo y el período se calcula por separado. No se manipulan fuentes eléctricas peligrosas ni radiactivas: son representaciones virtuales. Las actividades preparan razonamiento experimental, pero no certifican destreza en material real.</p><h2>Tu avance</h2><p>Controles respondidos correctamente, último repaso y cuadernos se guardan en este navegador. No se piden datos personales ni se envían respuestas de esta sección a Google. Cambiar de equipo o borrar datos del sitio puede eliminar ese avance. Las marcas indican actividades comprobadas, no dominio certificado del programa.</p></section></main>'''
write(Path('activities/oaf/programa.html'),shell('Programa y normas','../../',b))
p=ROOT/'catalog.json';catalog=json.loads(p.read_text());catalog['years']=[y for y in catalog['years'] if y['id']!='oaf'];subjects=[]
for a in AREAS:
 topics=[]
 for u in [u for u in UNITS if u['area']==a['id']]:
  aid=u['id'];activity=dict(id=aid,title=u['title'],description='Cuatro lecciones en español, instrumentos interactivos, investigación y repaso con explicaciones.',format='Lección e investigación',duration='A tu ritmo',image='activities/oaf/cover.svg',href='activities/oaf/'+u['path'])
  topics.append(dict(id=u['slug'],name=u['title'],description=' · '.join(u['topics']),primaryActivity=aid,appTitle=u['title'],activities=[activity]))
 subjects.append(dict(id=a['id'],name=a['name'],description=a['intro'],topics=topics))
catalog['years'].append(dict(id='oaf',name='Olimpíada Argentina de Física',shortName='OAF',subjects=subjects));p.write_text(dump(catalog)+'\n')
print(f'OAF: {len(AREAS)} áreas, {len(UNITS)} unidades, {sum(len(u["lessons"]) for u in UNITS)} lecciones y {sum(len(u["lessons"])+len(u["review"]) for u in UNITS)} preguntas de repaso.')
